# -*- coding: utf-8 -*-
p='output/Аудит_НИОКР_интерактивная_модель.html'
s=open(p,encoding='utf-8').read()
def rep1(old,new):
    global s
    assert s.count(old)==1, "NOT UNIQUE/FOUND: "+repr(old[:80])
    s=s.replace(old,new)
def repN(old,new,n=None):
    global s
    c=s.count(old)
    assert c>=1 and (n is None or c==n), "COUNT %d for %r"%(c,old[:80])
    s=s.replace(old,new)
    print("x%d"%c,repr(old[:60]))

